<?php

declare(strict_types=1);

namespace Tests;

use App\Support\KeyCipher;
use Database\Seeds\DatabaseSeeder;

/** Game keys are inventory: created once, never regenerated by a re-run or a restart, never reused once delivered. */
final class KeyInventoryTest extends DbTestCase
{
    private KeyCipher $cipher;

    protected function setUp(): void
    {
        parent::setUp();
        $this->cipher = KeyCipher::fromBase64((string) $_ENV['KEY_ENCRYPTION_KEY']);
        self::$pdo->exec('SET FOREIGN_KEY_CHECKS = 0');
        foreach (['stripe_events', 'cart_items', 'order_items', 'game_keys', 'orders', 'users'] as $table) {
            self::$pdo->exec("TRUNCATE TABLE $table");
        }
        self::$pdo->exec('SET FOREIGN_KEY_CHECKS = 1');
    }

    /** @return array<string, string> key id => encrypted key */
    private function snapshot(): array
    {
        return self::$pdo->query('SELECT id, key_enc FROM game_keys ORDER BY id')->fetchAll(\PDO::FETCH_KEY_PAIR);
    }

    public function testASecondSeedRunNeitherAddsNorChangesAKey(): void
    {
        $seeder = new DatabaseSeeder(self::$pdo, $this->cipher);
        $seeder->run();
        $first = $this->snapshot();
        $orders = (int) self::$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();

        $seeder->run();
        $seeder->run();

        self::assertSame($first, $this->snapshot(), 'same rows, same ciphertext: nothing regenerated or re-encrypted');
        self::assertSame($orders, (int) self::$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn(), 'demo orders are not repeated either');
    }

    public function testSoldOutOffersAreNotRefilledByTheSeeder(): void
    {
        $seeder = new DatabaseSeeder(self::$pdo, $this->cipher);
        $seeder->run();
        $offerId = (int) self::$pdo->query("SELECT offer_id FROM game_keys GROUP BY offer_id ORDER BY offer_id LIMIT 1")->fetchColumn();
        self::$pdo->exec("UPDATE game_keys SET status = 'sold', sold_at = NOW() WHERE offer_id = $offerId");
        $before = (int) self::$pdo->query('SELECT COUNT(*) FROM game_keys')->fetchColumn();

        $seeder->run();

        self::assertSame($before, (int) self::$pdo->query('SELECT COUNT(*) FROM game_keys')->fetchColumn());
        self::assertSame(0, (int) self::$pdo->query("SELECT COUNT(*) FROM game_keys WHERE offer_id = $offerId AND status = 'available'")->fetchColumn(), 'a sold-out offer stays sold out');
    }

    public function testKeysAreRandomNotDerivableFromTheSeederCode(): void
    {
        (new DatabaseSeeder(self::$pdo, $this->cipher))->run();
        $first = $this->cipher->decrypt((string) self::$pdo->query('SELECT key_enc FROM game_keys ORDER BY id LIMIT 1')->fetchColumn());
        self::$pdo->exec('SET FOREIGN_KEY_CHECKS = 0');
        foreach (['order_items', 'game_keys', 'orders'] as $table) {
            self::$pdo->exec("TRUNCATE TABLE $table");
        }
        self::$pdo->exec('SET FOREIGN_KEY_CHECKS = 1');

        (new DatabaseSeeder(self::$pdo, $this->cipher))->run();
        $again = $this->cipher->decrypt((string) self::$pdo->query('SELECT key_enc FROM game_keys ORDER BY id LIMIT 1')->fetchColumn());

        self::assertNotSame($first, $again);
        self::assertMatchesRegularExpression('/^[A-Z0-9]{5}(-[A-Z0-9]{5}){2}$/', $again);
    }

    public function testTheSeederRefusesToAddKeysUnderAnotherSecret(): void
    {
        (new DatabaseSeeder(self::$pdo, $this->cipher))->run();
        self::$pdo->exec('DELETE FROM game_keys WHERE id > (SELECT m FROM (SELECT MIN(id) + 5 AS m FROM game_keys) x)'); // leaves keys, makes room to add some
        $before = $this->snapshot();

        $this->expectException(\RuntimeException::class);
        $this->expectExceptionMessage('cannot be decrypted');
        try {
            (new DatabaseSeeder(self::$pdo, KeyCipher::fromBase64(base64_encode(random_bytes(32)))))->run();
        } finally {
            self::assertSame($before, $this->snapshot(), 'nothing was added');
        }
    }

    public function testDeliveredKeysRecordWhenTheyWereSoldAndWhichOrderOwnsThem(): void
    {
        (new DatabaseSeeder(self::$pdo, $this->cipher))->run();

        $rows = self::$pdo->query("SELECT order_id, sold_at, reserved_until FROM game_keys WHERE status = 'sold'")->fetchAll();

        self::assertNotEmpty($rows);
        foreach ($rows as $row) {
            self::assertNotNull($row['order_id']);
            self::assertNotNull($row['sold_at']);
            self::assertNull($row['reserved_until']);
        }
        self::assertSame(0, (int) self::$pdo->query("SELECT COUNT(*) FROM game_keys WHERE status = 'available' AND (order_id IS NOT NULL OR sold_at IS NOT NULL)")->fetchColumn());
    }

    public function testTheImportScriptAddsOnlyNewKeysAndNeverTouchesDeliveredOnes(): void
    {
        (new DatabaseSeeder(self::$pdo, $this->cipher))->run();
        $offerId = (int) self::$pdo->query('SELECT id FROM offers ORDER BY id LIMIT 1')->fetchColumn();
        $file = tempnam(sys_get_temp_dir(), 'keys');
        file_put_contents($file, "IMPORT-AAAAA-11111\nIMPORT-BBBBB-22222\nIMPORT-AAAAA-11111\n");
        $run = static fn (): string => (string) shell_exec(sprintf(
            'DB_NAME=%s php %s %d %s 2>&1',
            escapeshellarg((string) ($_ENV['DB_NAME'] ?? 'keymart_test')),
            escapeshellarg(__DIR__ . '/../bin/import_keys.php'),
            $offerId,
            escapeshellarg($file),
        ));

        self::assertStringContainsString('2 key(s) added', $run());
        self::$pdo->exec("UPDATE game_keys SET status = 'sold', sold_at = NOW() WHERE key_hash = '" . KeyCipher::fingerprint('IMPORT-AAAAA-11111') . "'");
        self::assertStringContainsString('0 key(s) added, 2 already known', $run());
        self::assertSame('sold', self::$pdo->query("SELECT status FROM game_keys WHERE key_hash = '" . KeyCipher::fingerprint('IMPORT-AAAAA-11111') . "'")->fetchColumn(), 'a delivered key is never put back on the shelf');
        unlink($file);
    }

    public function testDoctorReportsEmptyStockAndAWrongSecret(): void
    {
        $failed = static fn (array $checks): array => array_column(array_filter($checks, static fn (array $c): bool => $c['status'] === 'fail'), 'name');

        self::assertSame(['Game keys'], $failed(\App\Support\Doctor::gameKeys(self::$pdo, (string) $_ENV['KEY_ENCRYPTION_KEY'])), 'no keys: nothing is buyable');

        (new DatabaseSeeder(self::$pdo, $this->cipher))->run();
        self::assertSame([], $failed(\App\Support\Doctor::gameKeys(self::$pdo, (string) $_ENV['KEY_ENCRYPTION_KEY'])));
        self::assertSame(
            ['KEY_ENCRYPTION_KEY matches the stored keys'],
            $failed(\App\Support\Doctor::gameKeys(self::$pdo, base64_encode(random_bytes(32)))),
            'keys stored under another secret are reported',
        );
    }
}
